export type DocumentStatus = (typeof DocumentStatus)[keyof typeof DocumentStatus];
export const MessageRole = { USER: "USER", ASSISTANT: "ASSISTANT", SYSTEM: "SYSTEM", TOOL: "TOOL" } as const;
export type MessageRole = (typeof MessageRole)[keyof typeof MessageRole];
export const AgentActionStatus = { PROPOSED: "PROPOSED", APPROVED: "APPROVED", EXECUTED: "EXECUTED", REJECTED: "REJECTED", FAILED: "FAILED" } as const;
export type AgentActionStatus = (typeof AgentActionStatus)[keyof typeof AgentActionStatus];
export const KnowledgeSourceType = { FILE: "FILE", URL: "URL", OFFICIAL_LAW: "OFFICIAL_LAW", KCSC: "KCSC", MANUFACTURER: "MANUFACTURER", INTERNAL_MANUAL: "INTERNAL_MANUAL", WEB: "WEB" } as const;
export type KnowledgeSourceType = (typeof KnowledgeSourceType)[keyof typeof KnowledgeSourceType];
export const KnowledgeStatus = { PENDING_PROCESSING: "PENDING_PROCESSING", PROCESSING: "PROCESSING", PENDING_REVIEW: "PENDING_REVIEW", APPROVED: "APPROVED", ARCHIVED: "ARCHIVED", FAILED: "FAILED" } as const;
export type KnowledgeStatus = (typeof KnowledgeStatus)[keyof typeof KnowledgeStatus];
export const TrustLevel = { OFFICIAL: "OFFICIAL", MANUFACTURER: "MANUFACTURER", INTERNAL_APPROVED: "INTERNAL_APPROVED", INTERNAL_UNVERIFIED: "INTERNAL_UNVERIFIED", WEB_UNVERIFIED: "WEB_UNVERIFIED" } as const;
export type TrustLevel = (typeof TrustLevel)[keyof typeof TrustLevel];
export const OntologyStatus = { CANDIDATE: "CANDIDATE", APPROVED: "APPROVED", REJECTED: "REJECTED", ARCHIVED: "ARCHIVED" } as const;
export type OntologyStatus = (typeof OntologyStatus)[keyof typeof OntologyStatus];
export const ImageSource = { UPLOADED: "UPLOADED", GENERATED: "GENERATED", INPAINTED: "INPAINTED" } as const;
export type ImageSource = (typeof ImageSource)[keyof typeof ImageSource];
export const ExportFormat = { TXT: "TXT", MARKDOWN: "MARKDOWN", PDF: "PDF", DOCX: "DOCX", HTML: "HTML", JSON: "JSON" } as const;
export type ExportFormat = (typeof ExportFormat)[keyof typeof ExportFormat];
export const ExportStatus = { QUEUED: "QUEUED", RUNNING: "RUNNING", DONE: "DONE", FAILED: "FAILED" } as const;
export type ExportStatus = (typeof ExportStatus)[keyof typeof ExportStatus];
export const TaskStatus = { QUEUED: "QUEUED", RUNNING: "RUNNING", BLOCKED: "BLOCKED", NEEDS_REVIEW: "NEEDS_REVIEW", DONE: "DONE", FAILED: "FAILED", CANCELED: "CANCELED" } as const;
export type TaskStatus = (typeof TaskStatus)[keyof typeof TaskStatus];

